{"function": "() => {
    // Extract the entire hierarchical structure
    const result = {
        articles: []
    };

    // Find the main article content
    const articleElement = document.querySelector('article');
    if (!articleElement) return result;

    // Get all direct children of the article that are lists
    const lists = articleElement.querySelectorAll('ul, ol');

    // The main structure seems to be in the first list
    const mainList = lists[0];
    if (!mainList) return result;

    // Process each list item at the top level
    const articleItems = mainList.children;

    for (let i = 0; i < articleItems.length; i++) {
        const articleItem = articleItems[i];
        const textNodes = [];

        // Collect all text nodes in this article item
        const walker = document.createTreeWalker(
            articleItem,
            NodeFilter.SHOW_TEXT,
            null,
            false
        );

        let node;
        while (node = walker.nextNode()) {
            textNodes.push(node.textContent.trim());
        }

        // Find article title (should contain "ARTICLE")
        const articleTitle = textNodes.find(t => t.includes('ARTICLE'));
        if (!articleTitle) continue;

        // Extract rules
        const rules = [];
        const ruleLinks = articleItem.querySelectorAll('li li a');

        ruleLinks.forEach(link => {
            // The rule text includes both the rule number and title
            const ruleText = link.textContent + link.nextSibling?.textContent;
            if (ruleText) {
                rules.push(ruleText.trim());
            }
        });

        result.articles.push({
            identifier: articleTitle,
            rules: rules
        });
    }

    return result;
}"}

